const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Semua','Informatika','Matematika','Sistem Informasi','Fisika','Kimia'];
const classes=[
{id:1,title:'Bedah Rekursif, Tree & Graph tanpa Pusing',category:'Informatika',name:'Salsa Putri',initial:'SP',major:'Teknik Informatika · Semester 6',rating:'4.9',quota:7,day:'22 Sep',time:'19.00',duration:90,desc:'Pahami rekursi dari dasarnya, telusuri tree, dan latihan menyelesaikan soal graph bareng mentor. Cocok untuk kamu yang sedang mengambil Struktur Data.',topics:['Base case dan cara kerja rekursi','Tree traversal: preorder, inorder, postorder','Graph, BFS, dan DFS']},
{id:2,title:'Kalkulus II: Taklukkan Integral Lipat',category:'Matematika',name:'Alya Rahma',initial:'AR',major:'Matematika · Semester 6',rating:'4.9',quota:5,day:'23 Sep',time:'16.00',duration:90,desc:'Belajar integral dengan langkah yang runtut. Kita mulai dari substitusi sampai integral lipat dua, lalu bahas soal bersama.',topics:['Teknik substitusi dan integral parsial','Menentukan batas integral','Latihan integral lipat dua']},
{id:3,title:'SQL & Database: Dari Query ke Studi Kasus',category:'Sistem Informasi',name:'Dimas Pratama',initial:'DP',major:'Sistem Informasi · Semester 5',rating:'4.8',quota:8,day:'24 Sep',time:'19.30',duration:120,desc:'Langsung praktik menulis query, menggabungkan tabel, dan merancang database yang rapi lewat studi kasus sederhana.',topics:['SELECT, WHERE, GROUP BY','INNER JOIN dan LEFT JOIN','Normalisasi database']},
{id:4,title:'Fisika Dasar: Pahami Gaya & Energi',category:'Fisika',name:'Rizky Hadi',initial:'RH',major:'Fisika · Semester 5',rating:'4.9',quota:4,day:'25 Sep',time:'15.00',duration:90,desc:'Pahami konsep Newton, energi, dan momentum menggunakan contoh di sekitar kita. Lengkap dengan pembahasan soal.',topics:['Diagram gaya dan hukum Newton','Usaha dan energi','Kekekalan momentum']},
{id:5,title:'Kimia Organik: Kenalan dengan Reaksi',category:'Kimia',name:'Nadia Putri',initial:'NP',major:'Kimia · Semester 6',rating:'4.8',quota:6,day:'26 Sep',time:'10.00',duration:90,desc:'Belajar mengenali gugus fungsi dan mekanisme reaksi dasar dengan contoh yang mudah diikuti.',topics:['Gugus fungsi organik','Reaksi substitusi dan eliminasi','Latihan identifikasi reaksi']},
{id:6,title:'Algoritma: Ngerti Big O dari Nol',category:'Informatika',name:'Fajar Aditya',initial:'FA',major:'Teknik Informatika · Semester 7',rating:'5.0',quota:3,day:'27 Sep',time:'13.00',duration:90,desc:'Cari tahu mengapa algoritma bisa cepat atau lambat dan bandingkan berbagai solusi lewat latihan langsung.',topics:['Kompleksitas waktu dan ruang','Sorting dan searching','Menganalisis algoritma sederhana']}
];
let user=null,view='explore',category='Semua',query='',sort='popular',booked=new Set(),mentor=false,register=false,custom=[],toastTimer;
const brand=()=>'<span class="brand"><span class="mark">n</span><span>ngerti<b>.in</b></span></span>';
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function login(){ $('#app').innerHTML=`<main class="login"><section class="story">${brand()}<div><span class="pill">✦ &nbsp; DARI MAHASISWA, UNTUK MAHASISWA</span><h1>Belajar bareng.<br><span>Paham beneran.</span></h1><p>Materi kuliah terasa rumit? Temukan teman belajar yang tepat. Patungan kelas, belajar dari kakak tingkat, tanpa bikin kantong berat.</p><div class="lesson-preview"><div class="card-top"><span class="pill">KELAS PATUNGAN</span><span class="rating">★ 4.9</span></div><h3>Yang tadinya bingung,<br>sekarang jadi ngerti.</h3><div class="preview-bottom"><div class="mentor"><span class="avatar">SP</span><div><strong>Belajar bareng mentor teruji</strong><small>Satu langkah lebih paham.</small></div></div><b style="color:var(--primary)">Rp5rb</b></div></div></div><div class="people"><span class="stack"><span class="avatar">SP</span><span class="avatar orange">AR</span><span class="avatar green">DP</span></span><span>Ilmu dibagi. Biaya dipatungi.</span></div></section><section class="signin"><span class="eyebrow muted">MULAI PERJALANANMU</span><h2>${register?'Kenalan dulu, yuk.':'Halo, teman belajar 👋'}</h2><p class="muted">${register?'Buat profil demo untuk menjelajahi kelas bersama.':'Masuk dan lanjutkan langkah kecilmu menuju paham.'}</p><form id="login-form">${register?'<label class="field">Nama lengkap<input name="name" required placeholder="Nama panggilanmu" maxlength="50"></label><div class="two-fields"><label class="field">NIM<input name="nim" required placeholder="Nomor mahasiswa"></label><label class="field">Program studi<select name="major">'+categories.slice(1).map(c=>`<option>${c}</option>`).join('')+'</select></label></div>':''}<label class="field">NIM atau email kampus<input name="identity" required autocomplete="username" placeholder="nama@kampus.ac.id"></label><label class="field">Kata sandi demo<div class="password-wrap"><input name="password" type="password" required minlength="6" autocomplete="off" placeholder="Minimal 6 karakter"><button type="button" id="show-pass">Lihat</button></div></label><p style="font-size:12px;color:var(--muted)">Gunakan data contoh, bukan kata sandi akun asli.</p><button class="primary full" type="submit">${register?'Buat profil demo':'Masuk demo'} <span>→</span></button></form><div class="divider">atau langsung lihat-lihat</div><button class="secondary full" id="guest">Jelajahi sebagai tamu &nbsp; ↗</button><footer>${register?'Sudah punya profil?':'Baru di Ngerti.in?'} <button class="text-button" id="toggle-auth">${register?'Masuk':'Daftar sekarang'}</button></footer><div class="demo-note">Versi demo · Tidak terhubung ke akun atau pembayaran asli.<br>Aktivitas demo berlaku selama halaman ini terbuka.</div></section></main>`;$('#toggle-auth').onclick=()=>{register=!register;login()};$('#show-pass').onclick=e=>{const i=$('[name=password]');i.type=i.type==='password'?'text':'password';e.target.textContent=i.type==='password'?'Lihat':'Tutup'};$('#guest').onclick=()=>enter('Teman');$('#login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);enter(f.get('name')||String(f.get('identity')).split('@')[0])}}
function enter(name){user={name};view='explore';render()}
function nav(v){view=v;query='';category='Semua';render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){if(!user)return login();$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-title">RUANG BELAJARMU</div><nav>${[['explore','⌘','Jelajah Kelas'],['schedule','▦','Jadwal Saya'],['assist','✦','Cari Mentor'],['mentor','◇','Ruang Mentor']].map(([v,i,t])=>`<button class="nav-button ${view===v?'active':''}" data-nav="${v}"><span class="nav-icon">${i}</span>${t}${v==='schedule'&&booked.size?` <span>${booked.size}</span>`:''}</button>`).join('')}<div style="height:24px"></div><button class="nav-button logout" id="logout"><span class="nav-icon">↪</span>Keluar</button></nav><div class="mentor-callout"><span style="color:var(--primary);font-size:24px">✧</span><h3>Paham? Bantu yang lain.</h3><p>Bagikan ilmu, buka kelasmu, dan tumbuh bersama.</p><button class="secondary" data-nav="mentor">Jadi mentor &nbsp; ↗</button></div></aside><div class="main"><header class="topbar"><span class="topbar-title">Ruang belajar / <span class="muted">${({explore:'Jelajah kelas',schedule:'Jadwal saya',assist:'Cari mentor',mentor:'Ruang mentor'})[view]}</span></span><span class="mobile-brand">${brand()}</span><div class="account"><span class="pill">DEMO</span><div><strong>${esc(user.name)}</strong><small>Mahasiswa · Mode demo</small></div><button class="avatar" id="account-button" aria-label="Keluar dari demo">${esc(user.name.slice(0,2).toUpperCase())}</button></div></header><main class="workspace" id="content"></main></div></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('#logout').onclick=logout;$('#account-button').onclick=logout;if(view==='explore')explore();if(view==='schedule')schedule();if(view==='assist')assist();if(view==='mentor')mentorPage()}
function logout(){user=null;mentor=false;booked.clear();custom=[];login()}
function footer(){return '<footer class="page-footer"><span>© 2026 Ngerti.in · Ilmu dibagi, biaya dipatungi.</span><span>Belajar jadi lebih dekat.</span></footer>'}
function explore(){$('#content').innerHTML=`<div class="greeting"><div><h1>Mau ngerti apa hari ini?</h1><p>Selalu ada teman yang bisa bantu kamu paham.</p></div><span class="pill">✧ &nbsp; SELANGKAH LEBIH PAHAM</span></div><section class="hero"><div><span class="eyebrow" style="color:#8676ba">KELAS KECIL, PEMAHAMAN BESAR</span><h2>Materi susah?<br><span>Kita pecahin bareng.</span></h2><p>Belajar langsung dari mahasiswa yang sudah melewatinya. Lebih santai, lebih nyambung.</p><button class="primary" id="browse">Temukan kelasmu &nbsp; →</button></div><div class="hero-price"><span class="pill">RAMAH KANTONG MAHASISWA</span><strong>Rp5.000<span style="font-size:16px;letter-spacing:0"> / sesi</span></strong><small>Mentor teruji &nbsp; · &nbsp; Maksimal 10 peserta</small></div></section><div class="search-row"><label class="searchbox"><span class="muted">⌕</span><input id="search" aria-label="Cari kelas atau mentor" placeholder="Cari materi, kelas, atau nama mentor..."></label><select id="sort" aria-label="Urutkan kelas"><option value="popular">Terpopuler</option><option value="rating">Rating tertinggi</option><option value="soon">Jadwal terdekat</option></select></div><div class="filters">${categories.map(c=>`<button class="filter ${category===c?'active':''}" data-cat="${c}">${c}</button>`).join('')}</div><div class="section-heading"><h2>Kelas buat kamu</h2><span id="count"></span></div><div class="cards" id="cards"></div>${footer()}`;$('#browse').onclick=()=>{$('#search').focus();$('#search').scrollIntoView({behavior:'smooth',block:'center'})};$('#search').oninput=e=>{query=e.target.value;cards()};$('#sort').value=sort;$('#sort').onchange=e=>{sort=e.target.value;cards()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));cards()});cards()}
function allClasses(){return [...classes,...custom]}
function filtered(){return allClasses().filter(c=>(category==='Semua'||c.category===category)&&`${c.title} ${c.name} ${c.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='rating'?Number(b.rating)-Number(a.rating):sort==='soon'?a.id-b.id:b.quota-a.quota)}
function card(c){const joined=booked.has(c.id);return `<article class="card"><div class="card-top"><span class="pill">${esc(c.category)}</span><span class="rating">★ ${c.rating}</span></div><h3>${esc(c.title)}</h3><div class="mentor"><span class="avatar ${c.id%3===1?'orange':c.id%3===2?'green':''}">${esc(c.initial)}</span><div><strong>${esc(c.name)} <span style="color:#7c6be0">✓</span></strong><small>${esc(c.major)}</small></div></div><div class="class-time">▦ &nbsp; ${esc(c.day)} · ${esc(c.time)} WIB &nbsp; · &nbsp; ${c.duration} menit</div><div class="quota"><span>${c.quota+(joined?1:0)} dari 10 teman bergabung</span><span>${joined?'Terdaftar':`${10-c.quota} tersisa`}</span></div><div class="progress"><span style="width:${(c.quota+(joined?1:0))*10}%"></span></div><div class="card-bottom"><div><strong>Rp5.000</strong><small> / sesi</small></div><button class="${joined?'secondary':'primary'}" data-detail="${c.id}">${joined?'Lihat kelas':'Ikut kelas'} &nbsp; ↗</button></div></article>`}
function wireCards(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.detail)))}
function cards(){const list=filtered();$('#count').textContent=`${list.length} kelas tersedia`;$('#cards').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>Belum ketemu kelasnya.</h3><p>Coba kata kunci lain atau pilih kategori Semua.</p></div>';wireCards()}
function modal(title,body){$('#modal').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" aria-label="Tutup">×</button></div>${body}`;$('#modal .close').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal()}
function detail(id){const c=allClasses().find(c=>c.id===id);if(!c)return;modal(esc(c.title),`<span class="pill">${esc(c.category)}</span><p style="margin-top:20px">${esc(c.desc)}</p><div class="mentor"><span class="avatar">${esc(c.initial)}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.major)} · ★ ${c.rating}</small></div></div><div class="detail-info">▦ &nbsp; ${esc(c.day)} · ${esc(c.time)} WIB<br>◷ &nbsp; ${c.duration} menit · Kelas daring<br>♧ &nbsp; ${10-c.quota-(booked.has(id)?1:0)} kursi tersedia</div><h3 style="font-size:15px">Yang akan kita pelajari</h3><ul>${c.topics.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="primary full" id="book">${booked.has(id)?'Lihat jadwal saya':'Ikut patungan · Rp5.000'}</button><p style="font-size:12px;text-align:center;margin-bottom:0">Kelas contoh · Tidak ada transaksi atau pertemuan sungguhan.</p>`);$('#book').onclick=()=>booked.has(id)?($('#modal').close(),nav('schedule')):payment(c)}
function payment(c){modal('Patungan satu langkah lagi.',`<p>${esc(c.title)}</p><div class="detail-info" style="display:flex;justify-content:space-between"><span>Total patungan</span><strong>Rp5.000</strong></div><label class="field">Metode pembayaran demo<select id="payment-method"><option>QRIS (simulasi)</option><option>GoPay (simulasi)</option><option>DANA (simulasi)</option></select></label><p>Ini simulasi. Tidak ada uang yang ditagih dan tidak perlu memasukkan data pembayaran.</p><button class="primary full" id="confirm-book">Konfirmasi patungan demo</button>`);$('#confirm-book').onclick=()=>{booked.add(c.id);$('#modal').close();nav('schedule');toast('Berhasil! Kelas ditambahkan ke jadwal demo kamu.')}}
function schedule(){$('#content').innerHTML=`<div class="greeting"><div><h1>Jadwal belajarmu</h1><p>Sisihkan waktu. Bawa rasa ingin tahu.</p></div><button class="secondary" id="find-more">Cari kelas</button></div><div class="cards">${booked.size?allClasses().filter(c=>booked.has(c.id)).map(card).join(''):'<div class="empty"><h3>Langkah pertama dimulai dari satu kelas.</h3><p>Kelas yang kamu ikuti akan muncul di sini.</p><button class="primary" id="empty-browse">Jelajahi kelas →</button></div>'}</div>${booked.size?'<p class="demo-note">Jadwal ini adalah simulasi. Link pertemuan belum tersedia.</p>':''}${footer()}`;$('#find-more').onclick=()=>nav('explore');if($('#empty-browse'))$('#empty-browse').onclick=()=>nav('explore');wireCards()}
function assist(){$('#content').innerHTML=`<div class="greeting"><div><h1>Temukan teman yang tepat.</h1><p>Ceritakan materi yang sedang ingin kamu pahami.</p></div></div><form class="assist" id="match"><span class="pill">✦ PENCOCOKAN MATERI</span><h3 style="margin-top:20px">Lagi kesulitan di bagian mana?</h3><label class="field"><textarea id="topic" rows="4" required placeholder="Misalnya: aku masih bingung bedanya BFS dan DFS..."></textarea></label><button class="primary">Carikan mentor →</button><p style="font-size:12px;margin:15px 0 0">Rekomendasi demo berdasarkan kata kunci materi.</p></form><div id="matches" class="cards"></div>${footer()}`;$('#match').onsubmit=e=>{e.preventDefault();const q=$('#topic').value.toLowerCase();const groups=[[/tree|graph|bfs|dfs|rekurs|algoritma|big o/,'Informatika'],[/integral|kalkulus|turunan|matematika/,'Matematika'],[/sql|database|query|basis data/,'Sistem Informasi'],[/fisika|newton|gaya|energi/,'Fisika'],[/kimia|reaksi|organik/,'Kimia']];const cat=groups.find(([r])=>r.test(q))?.[1];$('#matches').innerHTML=cat?allClasses().filter(c=>c.category===cat).map(card).join(''):'<div class="empty"><h3>Belum ada kecocokan yang spesifik.</h3><p>Coba sebut materi seperti integral, SQL, rekursi, atau hukum Newton.</p></div>';wireCards()}}
function mentorPage(){$('#content').innerHTML=`<div class="greeting"><div><h1>${mentor?'Ruang mentormu':'Ilmu yang kamu punya, bisa berarti.'}</h1><p>${mentor?'Bantu teman kuliah memahami materi, satu kelas setiap waktu.':'Mulai berbagi melalui kelas kecil yang lebih personal.'}</p></div>${mentor?'<button class="primary" id="new-class">+ Buat kelas</button>':''}</div>${mentor?`<div class="stats"><div class="stat"><span>Kelas dibuat</span><strong>${custom.length}</strong></div><div class="stat"><span>Peserta demo</span><strong>${custom.filter(c=>booked.has(c.id)).length}</strong></div><div class="stat"><span>Pendapatan demo</span><strong>Rp${(custom.filter(c=>booked.has(c.id)).length*5000).toLocaleString('id-ID')}</strong></div></div><div class="cards">${custom.length?custom.map(card).join(''):'<div class="empty"><h3>Kelas pertamamu menunggu.</h3><p>Pilih materi yang kamu kuasai dan buat kelas demo.</p></div>'}</div>`:`<form class="assist" id="mentor-form" style="max-width:620px"><span class="pill">PENDAFTARAN MENTOR DEMO</span><h3 style="margin-top:22px">Bantu temanmu jadi lebih paham.</h3><div class="two-fields"><label class="field">Bidang yang dikuasai<select name="subject">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">IPK<input name="gpa" type="number" min="3.5" max="4" step=".01" required placeholder="3.85"></label></div><p>Profil mentor pada versi ini adalah simulasi. Verifikasi dokumen akademik belum terhubung.</p><label style="font-size:14px;display:flex;gap:9px;margin-bottom:22px"><input type="checkbox" required> Saya ingin mencoba alur mentor demo.</label><button class="primary">Aktifkan mode mentor →</button></form>`}${footer()}`;if(!mentor)$('#mentor-form').onsubmit=e=>{e.preventDefault();mentor=true;mentorPage();toast('Mode mentor demo aktif.')};else $('#new-class').onclick=createClass;wireCards()}
function createClass(){modal('Buka kelas pertamamu.',`<form id="create-class"><label class="field">Judul kelas<input name="title" required maxlength="90" placeholder="Contoh: Pahami Dasar Pemrograman Python"></label><div class="two-fields"><label class="field">Kategori<select name="category">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Durasi<select name="duration"><option value="90">90 menit</option><option value="120">120 menit</option></select></label></div><label class="field">Jadwal<input name="date" type="datetime-local" min="${new Date(Date.now()+3600000).toISOString().slice(0,16)}" required></label><label class="field">Deskripsi<textarea name="desc" required rows="3" maxlength="600" placeholder="Apa yang akan dipelajari bersama?"></textarea></label><button class="primary full">Terbitkan kelas demo</button></form>`);$('#create-class').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=new Date(f.get('date'));if(d<=new Date())return toast('Pilih jadwal di masa depan.');custom.push({id:Date.now(),title:f.get('title'),category:f.get('category'),duration:Number(f.get('duration')),desc:f.get('desc'),name:user.name,initial:user.name.slice(0,2).toUpperCase(),major:'Mentor demo',rating:'5.0',quota:0,day:d.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}),time:d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),topics:['Materi dan diskusi bersama','Latihan dan tanya jawab']});$('#modal').close();mentorPage();toast('Kelas demo berhasil diterbitkan.')}}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_classes',description:'Filter the visible class catalog by a topic or mentor name in the demo.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be a string');if(!user)throw new Error('Enter guest demo first');view='explore';query=input.query;category='Semua';render();$('#search').value=query;cards();return {classes:filtered().map(c=>({id:c.id,title:c.title}))}}})).catch(()=>{})}catch{}}
login();
